#requires -RunAsAdministrator
#requires -Version 5.1
[CmdletBinding()]param([string]$Target)
$root='C:\ProgramData\BlueRidge\SMBReports';$logs='C:\ProgramData\BlueRidge\Logs';New-Item -ItemType Directory -Force -Path $root,$logs|Out-Null;$s=Get-Date -Format yyyyMMdd-HHmmss;$d=Join-Path $root "smb-$env:COMPUTERNAME-$s";New-Item -ItemType Directory -Force -Path $d|Out-Null;Start-Transcript -Path (Join-Path $logs 'smb-share-diagnostics.log') -Append|Out-Null
try{Get-SmbShare|Select Name,Path,Description,CurrentUsers,FolderEnumerationMode,EncryptData,ContinuouslyAvailable|Export-Csv (Join-Path $d shares.csv) -NoTypeInformation;Get-SmbSession|Select ClientComputerName,ClientUserName,NumOpens,Dialect,Encrypted,Signed|Export-Csv (Join-Path $d sessions.csv) -NoTypeInformation;Get-SmbOpenFile|Select ClientComputerName,ClientUserName,Path,Permissions,SessionId|Export-Csv (Join-Path $d open-files.csv) -NoTypeInformation;Get-SmbServerConfiguration|Format-List *|Out-File (Join-Path $d server-config.txt);Get-SmbClientConfiguration|Format-List *|Out-File (Join-Path $d client-config.txt);Get-Service LanmanServer,LanmanWorkstation|Select Name,Status,StartType|Export-Csv (Join-Path $d services.csv) -NoTypeInformation;if($Target){Resolve-DnsName $Target -ErrorAction SilentlyContinue|Out-File (Join-Path $d target-dns.txt);Test-NetConnection $Target -Port 445|Format-List *|Out-File (Join-Path $d target-445.txt)};Write-Host "SMB diagnostic bundle: $d" -ForegroundColor Green}finally{Stop-Transcript|Out-Null}
